/*
 * Сборка отчёта «Интерактивная 3D-модель ДВС» в формате Word (build/raw.docx; дальше — build.sh).
 * Таблицы и большинство чисел берутся из results/*.json (npm run calc), рисунки — из figures/png
 * (npm run figures), снимки экрана симуляции — из report/screenshots. Запуск: bash report/build.sh
 *
 * Рисунки и таблицы вызываются по ключам (numberedFigure, numberedTable), а ссылки на них в тексте —
 * через figureNumber(key) и tableNumber(key) по спискам FIGURE_ORDER и TABLE_ORDER; в конце проверяется,
 * что порядок в тексте совпадает со списками. Содержание — поле TOC; номера страниц подставляются
 * вторым проходом из build/toc_pages.json (toc_pages.py).
 *   relativeToDeadCentre(phase) — угол цикла словами: «13° после ВМТ»
 */
const fs = require('fs');
