const comma = (x, n = 1) => (typeof x === 'number' ? x.toFixed(n) : String(x)).replace('.', ',');
const FIGURE_ORDER = ['arch', 'kin', 'pphi', 'pv', 'wiebe', 'dieselpv', 'balance', 'torque', 'valve', 'timingshot', 'gearsshot', 'speed', 'simchar', 'mainshot', 'pvshot'];
