const figureNumber = (k) => FIGURE_ORDER.indexOf(k) + 1;
const tableNumber = (k) => TABLE_ORDER.indexOf(k) + 1;
const figuresUsed = [], tablesUsed = [];
const numberedFigure = (k, ...a) => { figuresUsed.push(k); return figure(...a); };
const numberedTable = (k, ...a) => { tablesUsed.push(k); return table(...a); };

const centered = (text, opt = {}) => new Paragraph({ alignment: AlignmentType.CENTER, spacing: { line: layout.LINE, lineRule: 'auto', before: opt.before || 0, after: opt.after || 0 }, children: textRuns(text, { bold: opt.bold }) });
const rightBlock = (text, opt = {}) => new Paragraph({ indent: { left: 5000 }, spacing: { before: opt.before || 0, line: layout.LINE, lineRule: 'auto' }, children: textRuns(text) });
